JOIN dbo.SanPhams sp ON sp.MaSanPham = v.Ma
WHERE NOT EXISTS (SELECT 1 FROM dbo.ThongSoKyThuats t WHERE t.UidSanPham = sp.Uid AND t.TenThongSo = v.Ten);
GO

-- Bộ ảnh: mỗi sản phẩm một ảnh (lấy từ AnhDaiDien)
INSERT INTO dbo.HinhAnhSanPhams (UidSanPham, DuongDan, Ordering)
SELECT s.Uid, s.AnhDaiDien, 1
FROM dbo.SanPhams s
WHERE s.AnhDaiDien IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dbo.HinhAnhSanPhams h WHERE h.UidSanPham = s.Uid);
GO

/* ---------------------------------------------------------------------
   C9. DỌN DỮ LIỆU CŨ (an toàn: không đụng tới sản phẩm đã nằm trong đơn hàng)
   --------------------------------------------------------------------- */
-- (a) Card VGA đang có: chuyển hãng sang hãng chip theo tên
UPDATE dbo.SanPhams SET MaThuongHieu = N'NVIDIA', NgayCapNhat = SYSDATETIME()
WHERE MaDanhMuc = N'VGA' AND ISNULL(MaThuongHieu, N'') <> N'NVIDIA'
  AND (TenSanPham LIKE N'%GeForce%' OR TenSanPham LIKE N'%RTX%' OR TenSanPham LIKE N'%GTX%');

UPDATE dbo.SanPhams SET MaThuongHieu = N'AMD', NgayCapNhat = SYSDATETIME()
WHERE MaDanhMuc = N'VGA' AND ISNULL(MaThuongHieu, N'') <> N'AMD'
  AND (TenSanPham LIKE N'%Radeon%' OR TenSanPham LIKE N'% RX %');
GO

-- (b) Xóa card VGA không thuộc NVIDIA hoặc AMD (nếu chưa có trong đơn hàng)
DELETE h FROM dbo.HinhAnhSanPhams h JOIN dbo.SanPhams s ON s.Uid = h.UidSanPham
WHERE s.MaDanhMuc = N'VGA' AND ISNULL(s.MaThuongHieu, N'') NOT IN (N'NVIDIA', N'AMD')
  AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
DELETE t FROM dbo.ThongSoKyThuats t JOIN dbo.SanPhams s ON s.Uid = t.UidSanPham
WHERE s.MaDanhMuc = N'VGA' AND ISNULL(s.MaThuongHieu, N'') NOT IN (N'NVIDIA', N'AMD')
  AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
DELETE s FROM dbo.SanPhams s
WHERE s.MaDanhMuc = N'VGA' AND ISNULL(s.MaThuongHieu, N'') NOT IN (N'NVIDIA', N'AMD')
  AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
GO

-- (c) Xóa sản phẩm trùng của bộ dữ liệu cũ (mã có dấu gạch dưới, vd CPU_INTEL_I5_12400F)
DELETE h FROM dbo.HinhAnhSanPhams h JOIN dbo.SanPhams s ON s.Uid = h.UidSanPham
WHERE s.MaSanPham LIKE N'%[_]%' AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
DELETE t FROM dbo.ThongSoKyThuats t JOIN dbo.SanPhams s ON s.Uid = t.UidSanPham
WHERE s.MaSanPham LIKE N'%[_]%' AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
DELETE s FROM dbo.SanPhams s
WHERE s.MaSanPham LIKE N'%[_]%' AND NOT EXISTS (SELECT 1 FROM dbo.ChiTietDonHangs c WHERE c.UidSanPham = s.Uid);
GO

-- (d) Xóa các hãng không còn sản phẩm nào (hãng bo mạch VGA cũ)
DELETE th FROM dbo.ThuongHieus th
WHERE th.MaThuongHieu IN (N'ZOTAC', N'SAPPHIRE', N'XFX', N'POWERCOLOR')
  AND NOT EXISTS (SELECT 1 FROM dbo.SanPhams s WHERE s.MaThuongHieu = th.MaThuongHieu);
GO

-- Kiểm tra: số sản phẩm theo loại, và hãng của card VGA (chỉ được có NVIDIA, AMD)
SELECT MaDanhMuc, COUNT(*) AS SoSanPham FROM dbo.SanPhams GROUP BY MaDanhMuc ORDER BY MaDanhMuc;
SELECT MaThuongHieu, COUNT(*) AS SoCardVGA FROM dbo.SanPhams WHERE MaDanhMuc = N'VGA' GROUP BY MaThuongHieu;
GO

/* ---------------------------------------------------------------------
   C10. BỔ SUNG 500 SẢN PHẨM MẪU (đợt 2): tập trung vào các hãng và mức thông số còn ít sản phẩm
       - RAM: thêm DDR4 / DDR5, 8GB / 64GB, bus 4800 / 5200 / 6400, hãng Patriot, Lexar...
       - VGA: thêm RTX 20/30, GTX 10/16, RX 5000/6000, bản 4GB / 6GB / 10GB. Hãng chỉ NVIDIA hoặc AMD.
       - SSD: thêm 250GB / 480GB / 500GB / 960GB, 4TB, PCIe 5.0, SATA, hãng Seagate, Patriot, Corsair...
       - CPU: socket LGA1200, LGA1851, AM4. Mainboard: AM4, LGA1200, LGA1851, AM5.
       - Nguồn, vỏ case, tản nhiệt, phụ kiện (loa, micro, bàn di, webcam...) thêm nhiều hãng mới.
       - Chạy lại nhiều lần được: sản phẩm đã có mã thì bỏ qua.
   --------------------------------------------------------------------- */
