SELECT fk.name AS KhoaNgoai,
       OBJECT_NAME(fk.parent_object_id)     AS BangCon,
       OBJECT_NAME(fk.referenced_object_id) AS BangCha
FROM sys.foreign_keys fk
ORDER BY BangCon, KhoaNgoai;
GO

